import{_ as t,o,c as a,a5 as s}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"3.4.15 Delete Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-15-delete-workspace/spec.md","filePath":"feature/agency-workspace/3-4-15-delete-workspace/spec.md"}'),i={name:"feature/agency-workspace/3-4-15-delete-workspace/spec.md"};function n(r,e,c,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-4-15-delete-workspace" tabindex="-1">3.4.15 Delete Workspace <a class="header-anchor" href="#_3-4-15-delete-workspace" aria-label="Permalink to &quot;3.4.15 Delete Workspace&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.4.15</td></tr><tr><td>Feature</td><td>Delete Workspace</td></tr><tr><td>Domain</td><td>Agency &amp; Workspace (FR 3.4)</td></tr><tr><td>Role</td><td>Agency OWNER ⚠ implemented per this reading, not formally confirmed by team</td></tr><tr><td>Version</td><td>2.4 — 2026-09-25 — resolved cascade-claim BA conflict: no cascade exists, documented as a known gap</td></tr><tr><td>Document status</td><td><strong>Implemented</strong></td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when an Agency owner confirms deletion of a Workspace by opening Workspace settings and typing the Workspace name in the danger-zone confirmation dialog.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Agency OWNER. ⚠ Implemented per this spec&#39;s Agency-OWNER reading (see <code>WorkspaceServiceImpl.deleteWorkspace</code>/<code>restoreWorkspace</code>, which use the Agency-OWNER precedent from <code>AgencyServiceImpl.removeAgency</code> because <code>@RequireRole</code> only knows WorkspaceMember roles, not Agency ownership); confirm with team if this was intended vs a different gate (e.g. workspace MANAGER).</li><li><strong>Purpose:</strong> Lets the owner remove a Workspace that is no longer used while keeping it recoverable for 30 days.</li><li><strong>Interface:</strong> A &quot;Danger Zone&quot; block inside Workspace settings (<code>detail.tsx</code>), visible only when <code>canManage</code> is true, with a Delete button that opens a confirmation dialog requiring the user to type the Workspace name before the destructive action is enabled. <strong>There is currently no Restore entry point in the frontend</strong> — <code>restoreWorkspace</code> exists only as a backend endpoint (<code>POST /api/v1/workspaces/{workspaceId}/restore</code>); no UI calls it today.</li><li><strong>Data Processing:</strong> The system marks the Workspace as soft-deleted (<code>status = SOFT_DELETED</code>, <code>deletedAt = now()</code>); restoring within 30 days reverses this (<code>status = ACTIVE</code>, <code>deletedAt = null</code>). <code>deleteWorkspace</code> only flips the Workspace&#39;s own status/timestamp fields — it does not cascade to Task/Campaign/Material records; those remain <code>ACTIVE</code> and are not automatically hidden. Access is not revoked mid-session either (BR-26 gates the delete action itself, not ongoing access to already-loaded data). Confirmed no cascade write in code this pass — this is a known gap, not just an unconfirmed claim.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Delete Workspace Dialog:</p><ul><li>A destructive confirmation dialog opened from the Danger Zone in Workspace settings, visible to the owner only (<code>canManage</code>).</li><li>The dialog requires the user to type the Workspace name before the destructive action (&quot;Confirm Delete&quot;) is enabled; a Cancel button closes it without action.</li><li>On success, a success toast is shown and the user is navigated to <code>/workspace</code>; on failure, an error toast is shown from the caught error message.</li><li>⚠ No restore screen exists in the frontend today — <code>workspaceService.restoreWorkspace</code> is defined in the FE service layer but nothing in the UI calls it. The &quot;matching restore entry&quot; described below is backend-only capability, not a shipped screen.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The Workspace identifier; the caller&#39;s authenticated identity; the typed Workspace name confirming the action.</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> The Workspace record with its status and deletion timestamp; the deletion window allowed for restoration.</li><li><strong>Output:</strong> Confirmation that the Workspace has been soft-deleted; on restore, the restored Workspace profile.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-26:</strong> Delete workspace is OWNER-only (Section5 appendix: &quot;Delete workspace is <code>OWNER</code>-only&quot;; implemented here as Agency OWNER — ⚠ see role-gate flag above). Soft-delete vs hard-delete, and the interaction with an active paid subscription, remain TBD (team decision) — invoices/payments are financial records that are likely not to be hard-deleted; the implemented code only ever soft-deletes.</li><li>A caller who is not the Agency OWNER, including the Workspace MANAGER → 403 <code>FORBIDDEN</code> (checked in <code>WorkspaceServiceImpl.deleteWorkspace</code>/<code>restoreWorkspace</code> against <code>agency.getOwnerId()</code>, not via <code>@RequireRole</code>).</li><li>Restoring later than 30 days after deletion (<code>WORKSPACE_RESTORE_WINDOW_DAYS = 30</code>) → 410 <code>RESTORE_WINDOW_EXPIRED</code>.</li><li>Restoring a Workspace whose status is not <code>SOFT_DELETED</code> → 400 <code>WORKSPACE_NOT_DELETED</code>.</li><li><strong>Known gap (not yet implemented):</strong> <code>deleteWorkspace</code> only sets the Workspace&#39;s own <code>status</code>/<code>deletedAt</code> — there is no cascade write to Task/Campaign/Material records, and no other code path was found that hides them based on the parent Workspace&#39;s status. Member/Client access is not revoked mid-session; it is simply that the deleted Workspace no longer appears in <code>listMyWorkspaces</code> (soft-deleted rows are still excluded there — see FR 3.4.10&#39;s known SOFT_DELETED-filter gap for the caveat on that). If cascading Task/Campaign/Material to inactive is required, it needs new code.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>The typed Workspace name must match the Workspace being deleted before the action is enabled (FE-only gate in <code>detail.tsx</code>, button <code>disabled</code> until <code>confirmName === name</code>).</li><li>The caller must be the Agency OWNER (BR-26); otherwise 403 <code>FORBIDDEN</code>, toast MSG39.</li><li>The Workspace must exist; otherwise 404 <code>WORKSPACE_NOT_FOUND</code>, toast MSG38.</li><li>The caller must belong to the Workspace&#39;s Agency; otherwise toast MSG40.</li><li>Restore is allowed only when the Workspace&#39;s status is <code>SOFT_DELETED</code> (otherwise 400 <code>WORKSPACE_NOT_DELETED</code>) and within 30 days of the deletion timestamp (otherwise 410 <code>RESTORE_WINDOW_EXPIRED</code>).</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>Owner opens Workspace settings (<code>detail.tsx</code>) and chooses Delete in the Danger Zone.</li><li>Dialog asks the owner to type the Workspace name to confirm; the Confirm Delete button stays disabled until the typed value matches.</li><li>FE calls <code>DELETE /api/v1/workspaces/{workspaceId}</code> (<code>workspaceService.deleteWorkspace</code>); System confirms the caller is the Agency OWNER (BR-26); otherwise the request fails with 403 <code>FORBIDDEN</code>.</li><li>System marks the Workspace as soft-deleted (<code>status = SOFT_DELETED</code>) and records the deletion timestamp (<code>deletedAt = now()</code>).</li><li>Task/Campaign/Material records inside the Workspace are left as-is (<code>ACTIVE</code>) — no cascade occurs; see Known gap under Business Rules.</li><li>The Workspace disappears from active listings; toast success message shown, user navigated to <code>/workspace</code>. It becomes restorable for 30 days via the backend endpoint only (no FE restore screen exists — see Screen Layout flag).</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>3.a1: Caller is not the Agency OWNER, even when they manage the Workspace (BR-26) → 403 <code>FORBIDDEN</code>, toast MSG39. 3.a2: The caller returns to Workspace settings without deleting.</li><li>3.b1: The Workspace does not exist (already deleted or invalid id) → 404 <code>WORKSPACE_NOT_FOUND</code>, toast MSG38. 3.b2: The caller returns to the Workspace list.</li><li>3.c1: The caller does not belong to this Workspace&#39;s Agency → toast MSG40. 3.c2: The caller is returned to their own Workspace list.</li><li>Restoring a Workspace that is not currently soft-deleted → 400 <code>WORKSPACE_NOT_DELETED</code>.</li><li>Restoring after the 30-day window → 410 <code>RESTORE_WINDOW_EXPIRED</code>.</li><li>The Workspace holds Tasks in progress or awaiting Client review when deleted → their statuses are untouched by delete/restore (no cascade — see Known gap under Business Rules); a restore simply flips the Workspace back to <code>ACTIVE</code>.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The Workspace is marked soft-deleted (<code>status = SOFT_DELETED</code>, <code>deletedAt</code> set) and is hidden from active listings.</li><li>The Workspace&#39;s Task/Campaign/Material records are unaffected (still <code>ACTIVE</code>) — no cascade exists today; see Known gap under Business Rules.</li><li>The Workspace remains restorable for 30 days via the backend <code>restoreWorkspace</code> endpoint (no FE screen currently exposes this).</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Immediate permanent deletion (only soft deletion is in scope).</li><li>A frontend Restore screen/entry point (backend capability exists; not yet surfaced in the UI — flag for product/FE to schedule).</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../BA/01-organization-structure.html">01-organization-structure.md</a>, <a href="./../../../BA/03-agency-workspace-management.html">03-agency-workspace-management.md</a></p>',27)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
